Skill.upsert_all([
  { id: 1, name: "Abominevole", description: "Quando un combattente deve effettuare un test di COR nei confronti di un\navversario Abominevole o di un gruppo di avversari uno dei quali è dotato di questa abilità, il test di COR\ndeve essere effettuato con 2d6. Solo il risultato naturale più basso è conservato. Se il combattente beneficia\ndi un effetto che gli permette di lanciare più d6 per il suo test di COR e di conservare il migliore, i due effetti\nsi annullano ed il tiro è effettuato normalmente, con un solo d6. Questa abilità non ha effetto se il\ncombattente che ne dispone ha un valore di COR, ma si applica normalmente se egli ottiene un valore di\nPAU (per esempio se ha Grido di guerra ed effettua una carica).", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 2, name: "Accanito", description: "Quando è Ucciso, un combattente accanito è rimosso dal campo di battaglia solo alla\nfine della fase in corso.​\nFino ad allora egli subisce i seguenti effetti:\n○​ è considerato a Ferita critica (pag.xx);\n○​ non può eseguire alcun Movimento di inseguimento;\n○​ perde l’uso delle abilità Devozione o Martire, se le possiede;\n○​ non può essere curato o sacrificato;\n○​ non conta per il calcolo dei punti missione.\nIn un’armata non è possibile inserire più di 5 combattenti con accanito ogni 200 p.a. del formato di gioco.\nIl totale dei p.a. spesi per reclutare combattenti accaniti non può essere superiore all’75% del formato di\ngioco.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 3, name: "Agguerrito", description: "I 5 ottenuti sui test di INI, ATT, DIF, TIR, COR e DIS del combattente possono essere\naperti come se fossero 6.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 4, name: "Alleanza", description: "Un combattente che possiede questa abilità può allearsi al popolo X o all’Alleanza\nX. Allora è considerato come un alleato dell’esercito.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: "X" },
  { id: 5, name: "Amato dagli dei", description: "I 4 ed i 5 ottenuti nelle prove di INI, ATT, DIF, TIR, COR e DIS del combattente\npossono essere aperti come se fossero 6.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 6, name: "Ambidestro", description: "Un combattente Ambidestro guadagna un dado di attacco supplementare per ogni\ndifesa riuscita. Questo dado di attacco è aggiunto alla riserva dei dadi in attacco del combattente per il\ncombattimento in corso. Il combattente può unire questo dado ad altri dadi di attacco per compiere Colpi da\nMaestro, se li può effettuare. Se il test di attacco dell’attaccante è un fallimento automatico, il giocatore che\ncontrolla il combattente Ambidestro può scegliere una delle seguenti opzioni:\n○​ conservare il suo dado di difesa;\n○​ rinunciare al suo dado di difesa (nessun test di difesa è richiesto) e guadagnare un dado di\nattacco supplementare.\nSe un combattente dispone sia di Contrattacco che di Ambidestro deve dichiarare quale delle due abilità\nutilizza prima di effettuare il proprio test di difesa.​\nAttenzione!​\nI dadi di attacco ottenuti grazie all’abilità Ambidestro sono persi alla fine del combattimento.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 7, name: "Artefatto", description: "Un combattente dotato di questa abilità può acquisire X artefatti. Questo valore\nsostituisce il numero di artefatti di cui normalmente il combattente può beneficiare (in funzione del suo rango\ne del suo status).", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: "X" },
  { id: 8, name: "Artificiere", description: "Quando un artificiere è schierato dispone di 2 segnalini: una trappola ed un’esca. Questi\nsegnalini possono essere piazzati, coperti, a 20 cm o meno dalla macchina da guerra alla quale il\ncombattete è associato. è tuttavia proibito piazzare tali segnalini a meno di 6 cm da una miniatura nemica, a\nmeno che essa non si trovi al di fuori della sua zona di schieramento. In seguito, quando una miniatura\n(amica o nemica) passa a 5 cm o meno da uno di questi segnalini esso viene rivelato.\n●​ Se si tratta di un’esca non succede niente;\n●​ Se si tratta di una trappola, questa esplode. Tutti i combattenti la cui base è situata (anche\nparzialmente) entro un raggio di 10 cm attorno alla trappola subiscono un tiro per ferire a forza 6. Se\npiù segnalini sono attivati dalla stessa miniatura, i loro effetti devono essere risolti uno dopo l’altro.\nSe alla sua attivazione un combattente si trova a portata di una trappola, se egli compie una qualunque\nazione la trappola si attiva.\nL’unico modo per non farla attivare è non far compiere alcuna azione al combattente. Una trappola non può\nessere attivata in nessun altro modo. Se essa è attivata da un combattente durante lo spostamento, questo\nè interrotto per il tempo necessario ad effettuare i tiri per ferire. Se il combattente sopravvive a questo test,\npuò terminare il suo spostamento.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 9, name: "Arto Aggiuntivo", description: "Un combattente con questa abilità può ricorrere ai suoi effetti all’inizio di ogni\npasso d’arme. Se lo fa egli scambia i suoi valori di ATT e DIF per la durata del passo d’arme in corso. Se\ndegli avversari dotati di Arto Aggiuntivo sono coinvolti nello stesso combattimento, il perdente del tiro di INI\ndeve annunciare per primo se ricorre a questa abilità.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 10, name: "Assassino", description: "Quando un Assassino ha Caricato durante la fase di attivazione, il primo tiro per\nFerire che egli provoca nel corso del primo combattimento al quale partecipa è risolto lanciando 3d6. Il\ngiocatore che controlla l’Assassino conserva solo due risultati a sua scelta per determinare le conseguenze\ndel tiro sulla Tabella delle Ferite. Questo dado è acquisito anche se il combattente è separato dal bersaglio\ndella sua carica al termine della separazione delle mischie, e anche se non gli ha inflitto alcun malus di\ncarica.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 11, name: "Assillo", description: "Un combattente dotato di questa abilità può, a scelta:\n○​ tirare e poi correre;\n○​ marciare, tirare e poi marciare di nuovo.\nL’uso di questa abilità va dichiarato all’attivazione della carta. In entrambi i casi la difficoltà dei tiri del\ncombattente aumenta di 1 punto fino al termine del turno se utilizza questi effetti. Il combattente non può\ntirare dopo aver effettuato una corsa.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 12, name: "Audacia", description: "Nelle prove di COR di un combattente dotato di questa abilità, un 1 non è un fallimento\n(anche se questo risultato è ottenuto dopo aver aperto il dado) ed un 5 può essere aperto come se fosse un\n6. Quando questo combattente piazza tutti i suoi dadi di combattimento in attacco, egli beneficia di un +1 ai\nrisultati finali dei suoi test di attacco fino al termine del combattimento.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 13, name: "Autorità", description: "Per ogni combattente dotato di questa abilità, il giocatore beneficia di un segnalino\nAutorità all’inizio di ogni turno, prima del tiro di tattica. In nessun momento della partita il numero di segnalini\ndi cui un giocatore dispone può superare il valore X, dove X è 1 + il numero di Personaggi Guerrieri Puri\npresenti nell’armata. Questo segnalino può essere utilizzato in diversi modi, sia durante la fase\nd’avvicinamento, sia durante la fase d’attivazione:\n○​ Quando un giocatore sta per passare il turno, egli può utilizzare 1 segnalino per riprendere\nimmediatamente la mano; quando un giocatore sta per essere di mano egli può usare 1\nsegnalino Autorità per passare il turno.\n○​ Quando il suo avversario sarà di mano, egli non potrà passare (questo utilizzo non è\ndisponibile se l’avversario è rimasto con una sola carta da attivare);\n○​ all’inizio della fase di corpo a corpo, dopo la divisione delle mischie, il giocatore può\nspendere 1 segnalino autorità per decidere di risolvere come prima mischia una mischia in\ncui è coinvolto un suo combattente con Autorità (se entrambi i giocatori possono usare\nquesto potere, solo il vincitore del tiro di tattica può farvi ricorso);\n○​ in un qualunque momento della fase di attivazione un giocatore può rimuovere X segnalini\nAutorità dalla propria riserva per rimuoverne X da quella nemica.\nTutti i segnalini Autorità usati nel corso di uno stesso turno, devono essere destinati ad attivare un effetto\ndiverso fra quelli sopra elencati. Esistono effetti che donano all’armata un segnalino Autorità. Questi effetti\nnon danno l’abilità Autorità ma solo un segnalino da spendere alle condizioni sopracitate.\nSe si ottiene un segnalino Autorità da magie/miracoli, il segnalino può essere speso per i vari usi tranne che\nquello di scegliere la prima mischia, a meno di avere combattenti con Autorità sul campo e scegliere la loro.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 14, name: "Balzo", description: "Un combattente dotato di questa abilità può effettuare fino a due balzi nel corso di qualsiasi\nspostamento durante il turno. Anche se si tratta di un’abilità attiva, Balzo può essere utilizzato da un\ncombattente in rotta. Balzo non può essere usato durante un Movimento in Copertura. Quando effettua un\nbalzo, un combattente può ignorare totalmente la presenza di alcuni ostacoli (elementi di scenario o altri\ncombattenti) e passarvi sopra senza alcuna penalità, in funzione della sua Taglia.\nAltezza Valicabile: Un combattente può ignorare miniature ed ostacoli di Taglia pari o inferiore alla sua se si\nsta spostando del suo valore di MOV o meno; può invece ignorare miniature ed ostacoli di una taglia\nsuperiore alla propria se si sta spostando di più del suo MOV. Il MOV di cui tenere conto è quello sulla carta\ndel combattente.\nLunghezza Valicabile: La possibilità di superare un ostacolo esiste solo in 2 casi:\nSe la distanza da superare al di sopra dell’ostacolo non è superiore al MOV del combattente (MOV/2 nel\ncaso di un movimento di inseguimento o di un combattente che effettua il balzo all’interno di Terreno\nDifficile).\nUn combattente può atterrare sull’ostacolo a patto che la superficie dell’ostacolo sia almeno uguale a quella\ndella sua base.\nIn tutte le altre situazioni il balzo è impossibile. Il superamento di un ostacolo non deve in nessun caso\nportare il combattente a superare il suo potenziale di spostamento. Se tale situazione si presenta, lo\nspostamento termina davanti all’ostacolo.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 15, name: "Bersaglio", description: "Se un combattente dotato di questa abilità è scelto come bersaglio diretto da un\ntiratore nemico, il valore di X associato all’abilità modifica la difficoltà del test di TIR.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: "X" },
  { id: 16, name: "Brutale", description: "Un combattente dotato di questa abilità infligge sempre penalità di carica ai suoi\navversari, anche a seguito di un impegno (anche se successivo a un movimento d’inseguimento) e anche se\nla sua possanza è inferiore a quella dell’avversario. Questa abilità non ha alcun effetto contro gli avversari\ndotati dell’abilità Irremovibile.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 17, name: "Carica Bestiale", description: "Quando un combattente dotato di questa abilità effettua una carica con\nsuccesso, egli beneficia di un dado d’attacco supplementare per il prossimo combattimento al quale\npartecipa in questo turno. Questo dado è acquisito anche se il combattente è separato dal bersaglio della\nsua carica al termine della separazione delle mischie, e anche se non gli ha inflitto alcun malus di carica. Un\ncombattente non può beneficiare di questa abilità più di due volte per turno.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 18, name: "Colossale", description: "Ogni Combattente con l’abilità Colossale è di Taglia Molto Grande. Possiede quindi\ndi base 7 Ferite e Possanza 4.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: nil },
  { id: 19, name: "Colpo da maestro", description: "Se più dadi di un combattente sono stati piazzati in attacco, alcuni di questi\npossono essere raggruppati per portare un colpo più potente. Quando è il turno del combattente di effettuare\nun attacco, il giocatore può sacrificare due dadi d’attacco per tentarne uno solo (esso conta come un solo\nattacco). Un solo dado viene lanciato per questo attacco e se quest’ultimo non viene parato, la forza del tiro\nper ferire causato dal Colpo da Maestro è pari alla somma del valore di FOR dell’attaccante al momento del\ntiro per Ferire più il valore X dell’abilità più il valore di ATT dell’attaccante, così come esso è scritto sulla sua\ncarta. Nel caso di un Colpo da Maestro il valore massimo raggiungibile di forza del colpo è pari a 15 + X.", created_at: "2025-12-28T14:40:46Z", updated_at: "2025-12-28T14:40:46Z", value: "X" },
  { id: 20, name: "Comando", description: "I combattenti entro X cm da un combattente con Comando possono utilizzare i suoi\nvalori di COR e DIS per effettuare le loro prove in queste abilità. Solo i valori stampati sulla Carta possono\nessere utilizzati. Se queste caratteristiche sono modificate, vengono comunque utilizzati i valori stampati\nsalvo diversamente specificato. Se il combattente con Comando è spaventoso, la sua PAU può essere\nutilizzata come COR, così come un combattente spaventoso può utilizzare il COR di un comandante COR.\nUn combattente non può mai ottenere un valore di PAU tramite Comando, a meno di particolari abilità. Un\ncombattente non può beneficiare dei bonus di comando che provengono da un combattente non\nappartenente al suo popolo ed armata.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 21, name: "Concentrazione", description: "Alcune caratteristiche dei combattenti dotati di questa abilità sono indicate in\ngrassetto. X indica il totale dei punti che il giocatore può suddividere ogni turno tra le caratteristiche elencate\nnella descrizione dell’abilità. Questi bonus possono essere attribuiti in qualsiasi momento e non\nnecessariamente in una sola volta, ma tenendo conto delle seguenti restrizioni:\n○​ L’aumento di una caratteristica non modifica in nessun caso un test già effettuato. Se, per esempio,\nun giocatore aumenta la RES di uno dei suoi combattenti dopo che quest’ultimo ha subito un test per\nFerire, per determinare il suo nuovo stato di salute viene presa in considerazione la RES prima\ndell’incremento.\n○​ La DIF e l’ATT di un combattente possono essere aumentate all’inizio di un passo d’arme, ma non\ndurante. Questi bonus sono validi fino al termine del turno.\n○​ I punti attribuiti sono validi fino alla fine del turno.\nUn combattente che dispone sia di Mutageno che di Concentrazione/X, nonostante sia un bonus “sulla\ncarta”, non può utilizzare queste abilità assieme ma deve scegliere quale delle due abilità utilizza (nel\nmomento in cui ne avrà necessità sceglierà quale usare).", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 22, name: "Consapevolezza", description: "Un combattente dotato di questa abilità sa sempre cosa accade entro 20 cm da\nlui al suo livello d’altitudine ed a quelli adiacenti. Quindi entro questo raggio da sé può agire con dei\nvantaggi. Il combattente beneficia dei seguenti vantaggi entro la portata di questa abilità:\n○​ ogni esploratore a portata non è più considerato nascosto (questo implica che se al termine di uno\nspostamento questo combattente arriva a portata di un Esploratore nemico, egli può\nimmediatamente agire contro di esso tirando o ricorrendo ad effetti mistici o a capacità speciali);\n○​ questo combattente può caricare i combattenti a portata anche se non li vede, così come può tirare\nsu di essi se nessun ostacolo solido (muro, albero, miniatura) interrompe la traiettoria del suo\nproiettile;\n○​ se può effettuare tiri indiretti e li effettua su un bersaglio a portata, questo combattente non subisce\nmalus in tiro a causa del tiro indiretto;\n○​ questo combattente può lanciare magie, miracoli o usare capacità speciali su bersagli a portata, e lo\npuò fare anche se in corpo a corpo. Non si tenga conto degli ostacoli, nemmeno se l’effetto prende\nla forma di un proiettile;\n○​ questo combattente può effettuare contromagie, assorbimenti o censure su avversari a portata, ma\nper le magie e le capacità deve comunque soddisfare anche le normali condizioni.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 23, name: "Contrattacco", description: "Un combattente dotato di Contrattacco può scegliere di guadagnare un dado di\nattacco supplementare per ogni difesa riuscita il cui risultato finale sia superiore di almeno 2 punti al risultato\nfinale dell’attacco parato. Un personaggio, un guerriero mago, o un monaco guerriero con questa abilità sulla\nsua carta di riferimento riesce nei contrattacchi con risultati superiori di 1 punto al test di difesa nemico.\nQuesto dado di attacco è aggiunto alla riserva di dadi in attacco del combattente per il combattimento in\ncorso. Il combattente può unire questo dado ad altri dadi di attacco per compiere Colpi da Maestro, se li può\neffettuare. Se il test di attacco dell’attaccante è un fallimento automatico, il giocatore che controlla il\ncombattente dotato di Contrattacco può scegliere una delle seguenti opzioni:\n○​ Conservare il suo dado di difesa;\n○​ Rinunciare al suo dado di difesa (nessun test di difesa è richiesto) e guadagnare un dado di attacco\nsupplementare.\nSe un combattente dispone sia di Contrattacco che di Ambidestro deve dichiarare quale delle due abilità\nutilizza prima di effettuare il proprio test di difesa.\nAttenzione!\nI dadi di attacco ottenuti grazie all’abilità contrattacco sono persi alla fine del combattimento.​", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 24, name: "Costrutto", description: "I Costrutti sono dotati delle abilità Immunità/Paura ed Immunità/Tossico. Inoltre,\nquando devono effettuare un test di DIS, si consideri che il valore di questa caratteristica sia pari a 0. I\nCostrutti non possono beneficiare dei vantaggi dell’abilità Comando.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 25, name: "Credente", description: "Un combattente dotato di questa abilità, che si trova nell’aura di fede di un fedele\nnon iconoclasta del suo esercito, non viene conteggiato insieme agli altri seguaci. Il fedele guadagnerà\ndirettamente X punti fede, dove X è il valore di Credente di questo combattente. Se questo combattente è\npresente all’interno di più aure, questo bonus si applica a tutti i fedeli. Se un fedele possiede questa abilità,\negli somma X ai punti fede fissi che genera ogni turno. Per gli iconoclasti i nemici credenti sono considerati\nnormali seguaci. Alcuni effetti di gioco permettono ai fedeli iconoclasti di conteggiare i seguaci della loro\nstessa armata nel calcolo della Fede Temporanea, ed in tal caso essi beneficiano dell’abilità Credente/X\ncome i fedeli ortodossi.\nCura: Si veda: Guarigione", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 26, name: "Destriero", description: "Un combattente dotato di questa abilità beneficia di un dado di combattimento\nsupplementare in corpo a corpo, a meno che non abbia effettuato una Carica con successo nello stesso\nturno.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 27, name: "Devozione", description: "Durante la sua attivazione, un mago può acquisire gemme di mana per mezzo di un\ncombattente del suo esercito dotato dell’abilità Devozione situato in un raggio di 10 cm attorno a lui. Non è\nnecessaria alcuna linea di vista, ma il mago deve essere libero da ogni avversario. Questo può essere fatto\nprima o dopo che il mago si sia mosso, disingaggiato o che abbia lanciato un sortilegio, ma solo durante la\nsua attivazione. Se le condizioni sono soddisfatte, il mago può aggiungere alla sua riserva da 1 a X gemme\ndi mana neutrali o gemme dell’elemento/alleanza di appartenenza del pezzo che la possiede quando le\nriceve da un Famiglio, da un Immortale o da un Elementale. Il combattente designato, per contro, subisce un\ntiro per Ferire con FOR uguale a 5 moltiplicata per il numero di gemme recuperate dal mago. Per questo tiro\nper ferire, la RES del bersaglio è considerata uguale a 0. Gli effetti che influenzano i risultati dei tiri per ferire\nsi applicano in ogni caso normalmente. Se il combattente è eliminato dal Tiro per Ferire, il mago ottiene\ntuttavia una gemma supplementare dello stesso elemento. Uno stesso mago può designare un solo\ncombattente dotato di Devozione per turno. Uno stesso combattente può essere designato una sola volta\nper turno.\nNota: L’abilità Devozione si considera affine all’abilità Mana dei Nexus. Uno stesso mago può quindi\nutilizzare una sola di queste capacità per turno: se usa Devozione su un combattente non può usare Mana\nsu un Nexus e vice-versa.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 28, name: "Disingaggio", description: "Se un test di disingaggio necessita di una difficoltà superiore a X, il test viene\neffettuato con difficoltà X. Questa abilità si applica solo ai disimpegni effettuati utilizzando l’INI, non ai\ndisimpegni in Forza.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 29, name: "Disperato", description: "Quando un combattente con Disperato si trova coinvolto in un combattimento contro\npiù avversari, o in un duello contro un avversario il cui valore (in p.a., così com’è stampato nella lista di\narmata) è superiore al suo, beneficia di un +1 ai risultati finali dei suoi Test di INI, ATT e DIF.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 30, name: "Effimero", description: "Durante ogni fase di mantenimento, viene lanciato 1d6 per ogni combattente dotato\ndi Effimero/X. Qualora il risultato sia superiore o uguale a X, il livello di Ferite del combattente è aggravato di\nuno. Se il test ha successo, il combattente effettua immediatamente un nuovo test alle stesse condizioni.\nTuttavia, qualunque sia il risultato di questo secondo test, esso non può determinarne un terzo. Un\ncombattente che disponga di questa abilità non può in nessun caso beneficiare di un test di Rigenerazione.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 31, name: "Enorme", description: "Ogni Combattente con l’abilità Enorme è di Taglia Molto Grande. Ogni Combattente\ncon l’abilità Enorme possiede quindi di base 6 Ferite e Possanza 3.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 32, name: "Esaltato", description: "Un 1 ottenuto in un test di Divination non è un fallimento per un Esaltato, nemmeno\nse questo risultato è stato ottenuto dopo aver aperto il dado.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 33, name: "Esploratore", description: "Al momento dello schieramento, gli Esploratori possono essere disposti ovunque sul\nterreno, anche al di fuori della zona di schieramento del loro esercito o in quella avversaria. Non è però\npermesso schierare un Esploratore a meno di 10 cm da un avversario. È invece possibile il contrario, ma è\nvietato schierare un combattente direttamente in contatto con un Esploratore. Se, al termine dello\nschieramento, un Esploratore è a più di 10 cm da ogni avversario, è considerato nascosto. Fintanto che\nrimane nascosto, l’Esploratore è considerato come un elemento scenico indistruttibile ed inalterabile di taglia\nrisibile (non costituisce alcun ostacolo). Egli non può quindi essere bersaglio di alcuna azione ma subisce\nnormalmente effetti che si applicano su aree di campo (come l’artiglieria a Zona). Un Esploratore non viene\npiù considerato nascosto se un nemico comincia o termina la propria attivazione entro 10 cm da lui o\ninsegue entro 10 cm da lui. Un combattente che rivela l’Esploratore durante la propria attivazione non può\nperò bersagliarlo direttamente (a meno che questi non abbia Consapevolezza), ne possono i combattenti\nattivati contemporaneamente ad esso. Un combattente attivato però in seguito (anche nello stesso turno di\ndichiarazione, per esempio grazie ad Autorità) può farlo. Un Esploratore è individuato anche se effettua una\ndelle seguenti azioni: Assalto; Tiro; lancio di un sortilegio; invocazione di un miracolo; utilizzo dell’abilità\nGrido di raduno. Comando si applica normalmente, anche se il combattente che ne è dotato è un\nEsploratore nascosto. Il massimo di combattenti dotati di Esploratore presenti in un’armata è pari a 1 + 2 per\nogni 100pa del formato di gioco, per un massimo del 75% in p.a. della lista.\nEssere di/X: Si veda: Immortale\nEtereo (Passiva; *) : I combattenti dotati di questa abilità beneficiano dei seguenti vantaggi\n●​ sono dotati dell’abilità Immunità/Stordito ed Immunità/Terreni Difficili;\n●​ riducono di 1 il totale delle ferite loro inflitte dai tiri per ferire, quindi 1 ferita diventa 0, 2 ferite\ndiventano 1 e così via;\n●​ non subiscono mai penalità di carica, in compenso essi possono infliggerle;\n●​ tutti i loro test di disingaggio hanno successo automaticamente (ma non possono disingaggiare nello\nstesso turno in cui sono stati caricati o ingaggiati);\n●​ possono passare attraverso gli ostacoli, che si tratti di un elemento di scenario o di una miniatura.\nNon possono però fermarsi ”all’interno” di un ostacolo;\nSe un combattente etereo spaventoso passa attraverso un combattente nemico, quest’ultimo deve effettuare\nun test di COR se non è immunizzato nei confronti della PAU del combattente;\nLa loro RES non può in nessun caso superare il valore di 10, e se lo supera viene considerata pari a 10.\nI combattenti con Etereo non beneficiano degli effetti dell’abilità Ossoduro, se la hanno.\nUn combattente con l’abilità Etereo (scritta sulla carta o acquisita in qualsiasi modo durante o prima del\ngioco) perde la capacità di attraversare gli oggetti intransitabili, intralcianti e il passaggio attraverso basette di\naltri combattenti fintanto che possiede un qualsiasi segnalino missione.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 34, name: "Evocatore", description: "Un combattente dotato di questa abilità aumenta di X il totale di possanza di\ncreature evocate che può controllare.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 35, name: "Fanatismo", description: "Quando un combattente dotato di questa abilità dovrebbe fuggire a causa della PAU,\nil giocatore che lo controlla deve effettuare un test di DIS alla stessa difficoltà del test di COR fallito (o del\ntest di Raduno fallito). Qualora fallisca nuovamente, il combattente fugge, ma se il test è riuscito, il\ncombattente subisce gli altri effetti della Rotta ma non fugge. Quando un combattente con Fanatismo piazza\nin attacco tutti i suoi dadi di combattimento, egli beneficia di un +1 al risultato finale dei suoi tiri per ferire in\ncorpo a corpo fino al termine del combattimento.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 36, name: "Feroce", description: "I risultati ”Stordito” (dopo aver applicato eventuali modificatori) sui tiri per Ferire in Corpo\na Corpo inflitti da un combattente dotato di questa abilità sono considerati come risultati ”1 Ferita”.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 37, name: "Fine lama", description: "Per questo combattente un 1 ottenuto in un test di Attacco non è un fallimento,\nnemmeno se questo risultato è stato ottenuto dopo aver aperto il dado.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 38, name: "Finta", description: "Quando un combattente con questa abilità riesce in un attacco in corpo a corpo e questo\nattacco non viene parato, allora il giocatore che lo controlla può decidere di effettuare una Finta. In tal caso,\ninvece di procedere ad un tiro per ferire, egli sceglie e fa perdere al suo avversario un dado da\ncombattimento posto in attacco o in difesa (ma non quello in riserva grazie a spadaccino).", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 39, name: "Flagello", description: "X indica un Personaggio, un tipo di combattente, un popolo, un’abilità, un rango etc...\nQuando un combattente dotato di Flagello/X effettua un test per ferire contro un avversario nei confronti del\nquale si applica il suo flagello, i danni sono letti una linea più in basso nella tabella delle ferite. Non è\npossibile scendere in questo modo sotto l’ultima linea. Se l’avversario bersaglio possiede Ossoduro, gli\neffetti delle due abilità si annullano a vicenda. Se un avversario rientra in più parametri del Flagello che si\npossiede, gli effetti di questa abilità non si cumulano (se si possiede, ad esempio, “Flagello/taglie grandi e\nwolfen” non si otterranno vantaggi addizionali contro un wolfen di taglia grande).", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 40, name: "Focus", description: "Un mago con questa abilità può aprire i 5 ottenuti nelle sue prove di POT come se fossero\n6.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 41, name: "Fortuna", description: "L’utilizzo di questa abilità può essere dichiarato una volta per turno, subito dopo un test\nd’INI, ATT, DIF, TIR, COR, DIS, Potere o Divination effettuato dal combattente che la possiede. Il test è\nannullato e rilanciato utilizzando lo stesso numero di dadi del primo tiro. Qualunque sia il risultato, non potrà\nessere rilanciato nuovamente.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 42, name: "Forza in Carica", description: "Quando un combattente dotato di questa abilità effettua una carica, egli può\ndecidere che la sua FOR sia sostituita da X. Questa modifica si applica fino alla fine del primo\ncombattimento al quale il combattente prende parte durante il turno. I possibili modificatori alla FOR del\ncombattente si applicano ugualmente a questo nuovo valore di FOR. Forza in carica / X non è presa in\nconsiderazione se il combattente effettua un Colpo da maestro. Il nuovo valore considerato rimane valido\nanche se il combattente è separato dal bersaglio che ha caricato.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 43, name: "Fratello di Sangue", description: "X indica il nome di uno o più personaggi al quale il combattente è legato.\nQuando questi combattenti fanno parte della stessa armata, il costo (in p.a.) di ciascuno di essi è diminuito\ndel 10% (Valore strategico arrotondato per eccesso rispetto a quello stampato nella lista di armata). Questa\nriduzione non modifica il costo degli eventuali artefatti, sortilegi, miracoli e capacità speciali opzionali,\ncompreso Sangue Divino. Inoltre, nel corso della battaglia, finché tutti questi combattenti rimangono ad una\ndistanza massima di 10 cm l’uno dall’altro, beneficiano entrambi dell’abilità Istinto di sopravvivenza. Se uno\ndi loro già dispone di questa abilità, egli aggiunge invece 1 punto al risultato finale dei suoi tiri di Istinto di\nsopravvivenza.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 44, name: "Furia Guerriera", description: "Per ogni suo combattente dotato di Furia Guerriera e coinvolto nello stesso\ncombattimento, il giocatore deve decidere se utilizzare o no questa abilità prima del test di INI. Se\ncombattenti avversari dotati di questa abilità sono coinvolti nello stesso combattimento, il perdente del tiro di\ntattica deve annunciare per primo quali dei suoi combattenti ricorreranno a Furia Guerriera. Un guerriero\nimmerso in questo stato di furore beneficia di un dado supplementare in corpo a corpo, ma tutti i suoi dadi\nsono automaticamente piazzati in attacco. Se un combattente utilizza questa abilità, gli effetti si applicano\nfino alla fine del turno, anche se il combattente partecipa ad un’altra mischia dopo un movimento di\ninseguimento. Un combattente costretto a mettere tutti o parte dei suoi dadi di combattimento in difesa non\npuò utilizzare Furia Guerriera.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 45, name: "Geniere", description: "Per ogni geniere associato ad una macchina da guerra è possibile piazzare una\nbarricata a 20 cm o meno dal congegno. Le dimensioni di una barricata sono le stesse di quelle di una base\ndi cavalleria e l’oggetto è considerato un ostacolo di taglia piccola (altezza 2 cm). Una barricata può essere\ndistrutta; essa ha RES 10 e 5 P.S. Le barricate non possono essere posizionate in modo tale da bloccare\ncompletamente l’accesso a un obiettivo o intrappolare un combattente avversario.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 46, name: "Gigantesco", description: "Ogni Combattente con l’abilità Gigantesco è di Taglia Molto Grande e possiede di\nbase 8 Ferite e Possanza 5.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 47, name: "Giusto", description: "I Giusti sono dotati di Immunità/Paura e non possono in nessun caso passare sotto il\ncontrollo del nemico. Inoltre, quando un Giusto piazza tutti i suoi dadi di combattimento in attacco, beneficia\ndi un +1 ai risultati finali dei suoi test d’Attacco fino al termine del turno. Questo bonus non può essere\ncumulato con quello dovuto all’abilità Audacia.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 48, name: "Grido di Guerra", description: "Quando un combattente dotato di questa abilità Carica un avversario, il suo\nCOR è rimpiazzato da una PAU uguale a X durante la carica. Le regole relative alla Paura vengono allora\napplicate con particolari conseguenze. Se il combattente dotato di Grido di Guerra è obbligato ad effettuare\nun Test di COR (nei confronti di un avversario spaventoso o un non morto, per esempio) può utilizzare il\nvalore PAU X al posto del suo COR. Se l’avversario Caricato è dotato di PAU uguale o inferiore a quella del\ncombattente che carica, quest’ultimo è immunizzato a questo valore come se avesse superato un test di\nCOR di uguale difficoltà.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 49, name: "Grido di raduno", description: "Questa abilità può essere attivata una volta per partita per ogni combattente che\nla possiede. Il giocatore che la utilizza deve annunciarlo all’inizio di qualsiasi fase strategica. Grido di raduno\ninfluenza tutti i combattenti della stessa armata in due modi:\n●​ Sono immediatamente ed automaticamente recuperati se sono in Rotta.\n●​ Beneficiano di un +1 al risultato finale dei loro test di COR fino alla fine del turno.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 50, name: "Guarigione", description: "Questa abilità e Cura sono la stessa abilità. Durante la fase di mantenimento, un\ncombattente dotato di questa abilità può guarire un combattente amico in contatto di base con lui o se\nstesso. Si lanci 1d6 se il risultato è superiore o uguale a X l’alleato scelto recupera 1 ferita. Un combattente\npuò utilizzare o beneficiare degli effetti di questa abilità una sola volta per turno, a meno che non venga\nespressamente detto diversamente. Un combattente che sia stato ”Ucciso” non può in nessun caso\nbeneficiare di Guarigione/X, anche se si trova ancora sul campo di battaglia grazie a qualche effetto di gioco\n(come l’abilità Accanito, ad esempio). Questa abilità non può essere usata su un bersaglio dotato di Punti\nStruttura.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 51, name: "Guerriero-Mago", description: "Un Guerriero-Mago beneficia dell’abilità Contrattacco e può cumulare azioni\nesclusive e Corsa col lancio di Incantesimi.\nEsempio\nEschelius può lanciare uno o più incantesimi (azione cumulativa) e poi dichiarare una carica (azione\nesclusiva), un ingaggio, un movimento in copertura o una corsa.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 52, name: "Iconoclasta", description: "I fedeli iconoclasti considerano come seguaci tutti i combattenti avversari invece\ndei propri. Un iconoclasta benefica delle Consacrazioni assegnate ai combattenti nemici. I combattenti\navversari dotati di Credente o Martire a portata dell’Aura di Fede di un Iconoclasta non possono beneficiare\ndegli effetti di queste abilità (i fedeli nemici contano il Credente come un normale seguace e non possono\nattivare Martire).", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 53, name: "Illuminato", description: "Un combattente dotato di questa abilità può aprire i 5 ottenuti sui test di Divination\ncome se fossero 6.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 54, name: "Immersione", description: "Un combattente dotato di questa abilità considera l’acqua come Terreno Difficile,\nla può pertanto attraversare e può sostare al suo interno. Egli considera inoltre qualunque terreno difficile\ncreato da effetti legati all’acqua come normale e non può subire riduzioni del proprio movimento a causa di\nmagie o abilità legate all’elemento acqua o a creature elementali dell’acqua.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 55, name: "Immortale", description: "Un’armata può includere solo immortali della stessa via dell’armata. Gli immortali\nappartengono alle tre vie di alleanza e godono di abilità particolari in base alla via a cui appartengono.\n●​ Destino: Sono dotati dell’abilità Consapevolezza.\n●​ Luce: Sono dotati dell’abilità Giusto.\n●​ Tenebre: Sono dotati dell’abilità Immunità/Paura ma sono ugualmente soggetti alla PAU di un\ncombattente Iperione. Inoltre tutti i combattenti considerano gli esseri delle tenebre come avversari\nspaventosi, anche se sono dotati di un valore di PAU superiore. Le regole della paura di applicano\nnormalmente. Infine, un essere delle tenebre non può passare sotto il controllo del nemico.\nTutti i combattenti immortali leggono le ferite inflitte dall’abilità Tossico una riga più in alto sulla tabella delle\nferite; questo effetto si cumula con Ossoduro.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 56, name: "Immunità", description: "Il combattente è immune o ignora gli effetti legati a X, o alle ferite localizzate nella\nzona X della tabella delle ferite.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 57, name: "Implacabile", description: "Un combattente dotato di questa abilità può eseguire fino a X movimenti di\ninseguimento in più rispetto a quelli ai quali ha normalmente diritto durante una stessa fase di\ncombattimento.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 58, name: "Infiltrazione", description: "Questa abilità è attivata subito prima del tiro di tattica del primo turno di gioco. Il\ncombattente può essere spostato di una distanza massima pari a X. Questo spostamento viene effettuato a\nlivello 0 ed in qualsiasi direzione. Esso non permette di ingaggiare un avversario ma può condurre il\ncombattente ad uscire dalla sua zona di schieramento e perfino entrare in quella del nemico. Se entrambe le\narmate dispongono di questa abilità, partendo dal giocatore che ha perso il tiro di tattica, i giocatori si\nalternano a far infiltrare i loro combattenti con questa abilità uno per volta nell’ordine che preferiscono.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 59, name: "Insensibile", description: "Quando un combattente dotato di questa abilità è bersaglio di un sortilegio o di\nun miracolo avversario (o quando si trova nella sua area di effetto), il giocatore che lo controlla deve lanciare\n1d6. Con un risultato superiore o uguale a X, il combattente non subisce l’effetto. Questo non significa che\nl’effetto dell’incantesimo o del miracolo è annullato, ma semplicemente che il combattente è sfuggito allo\nstesso.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 60, name: "Iperione", description: "Gli iperoni beneficiano delle abilità Alleanza/Cynwall e Immunità/Paura. Inoltre, tutti i\ncombattenti appartenenti ai Meandri delle Tenebre (anche i non morti), così come gli Elementali e gli\nImmortali delle tenebre, considerano gli Iperoni avversari spaventosi, anche se la loro PAU è superiore al\nCOR dell’Iperione. Nei confronti di un Iperone, un combattente spaventoso considera la sua PAU come COR\ned il COR dell’Iperione come PAU. Si applicano quindi le normali regole relative alla paura.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 61, name: "Irremovibile", description: "Un combattente dotato di questa abilità non subisce mai le penalità dovute ad\nuna carica, nemmeno quelle inflitte da un combattente con l’abilità Brutale.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 62, name: "Istinto di Sopravvivenza", description: "Prima di ogni tiro per ferire effettuato contro un combattente dotato di\nquesta abilità, il giocatore che lo controlla può lanciare 1d6 (questo è detto tiro di Istinto). Con un 6 il tiro per\nFerire è annullato. A meno che non sia espressamente dichiarato da un effetto di gioco, il cumulo di effetti\nche riducono il risultato da ottenere nelle prove di Istinto di Sopravvivenza non permette di avere successo\nnella prova con un risultato inferiore a 5. Nel corso di un passo d’arme un combattente con questa abilità che\nabbia successo nella sua prova di Istinto non può effettuare altri tiri di Istinto fino al termine del passo\nd’arme.​\nQuesto effetto non si applica ai tiri per ferire causati dalle abilità Devozione e Martire.\nEsempio\nSethin dispone di Istinto di Sopravvivenza. Un vicario a portata riduce il valore da ottenere sul dado da 6 a 5.\nA questo punto un Neuromante non potrà ulteriormente diminuire questo valore col suo potere\nPreservazione, dato che Sethin riesce già col 5. Al contrario Virae ha un oggetto che le permette di ridurre la\nsua aura di fede per riuscire con risultati minori nelle sue prove di Istinto di Sopravvivenza. Dato che\nl’oggetto stesso specifica i risultati con cui Virae riesce, Virae può avere successo nei suoi test di Istinto con\nmeno di 5.\nEsempio\nVirae fronteggia tre avversari. Durante il passo d’arme nemico un avversario la attacca con successo e Virae\ndecide di effettuare una prova di Istinto ed ottiene 6: il tiro per ferire è annullato. Ora Virae non potrà\neffettuare altri tiri di istinto fino al termine del passo d’arme, quindi gli attacchi degli altri due avversari non\npotranno essere ignorati grazie a questa abilità.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 63, name: "Maestria degli Arcani", description: "Una volta per turno, quando un mago dotato di questa abilità non dispone\ndel mana necessario per lanciare un sortilegio (e solo se non ne dispone), egli può abbassare\ntemporaneamente il suo POT per acquisire l’energia magica mancante. In termini di gioco egli può subire un\nmalus di -X nella sua prossima prova di POT per ottenere X gemme di mana, dove X è il costo della magia\nche vuole lanciare (queste gemme non occupano spazio nella sua riserva e sono immediatamente spese per\nlanciare la magia. X può al massimo essere pari al POT del mago -1). Se il mago dispone di una parte delle\ngemme necessarie in riserva, egli deve utilizzarle e ridurrà del numero di gemme così spese il valore di X.\nQuando si ricorre a questa abilità è impossibile rinforzare la maestria del sortilegio spendendo altre gemme\ndi mana (si applicano normalmente effetti in grado di garantire dadi di maestria senza spese). Se la magia\npuò essere potenziata o richiede la spesa di gemme addizionali, queste non possono essere spese mentre\nsi ricorre a Maestria degli Arcani. Se un mago dispone di un artefatto in grado di fornirgli mana o se può\nacquisire mana con altri mezzi (sortilegio, fonte di mana attiva, ecc. ), il giocatore può scegliere di ricorrere a\nMaestria degli Arcani piuttosto che utilizzare l’altra fonte.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 64, name: "Maestro arciere", description: "I combattenti dotati di questa abilità possono effettuare un tiro\nsupplementare durante la loro attivazione.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "balestriere" },
  { id: 65, name: "Maledetto", description: "Un Maledetto non può rilanciare nessun tiro di dado, nemmeno se un effetto di\ngioco lo autorizza normalmente a farlo. Inoltre non può aprire i 6 (dovrà comunque aprire gli 1).", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 66, name: "Martire", description: "Durante la sua attivazione, un fedele può acquisire F.T. per mezzo di un combattente del\nsuo esercito dotato dell’abilità Martire situato in un raggio di 10 cm attorno a lui. Non è necessaria alcuna\nlinea di vista, ma il fedele deve essere libero da ogni avversario. Questo può essere fatto prima o dopo che il\nmago si sia mosso, disingaggiato o che abbia lanciato un sortilegio, ma solo durante la sua attivazione. Se le\ncondizioni sono soddisfatte, il fedele può aggiungere alla sua riserva da 1 a X punti fede. Il combattente\ndesignato, per contro, subisce un tiro per Ferire con FOR uguale a 5 moltiplicata per il numero di F.T.\ntrasmessi al fedele. Per questo tiro per ferire, la RES del bersaglio è considerata uguale a 0. Gli effetti che\ninfluenzano i risultati dei tiri per ferire si applicano normalmente. Se il combattente è eliminato dal Tiro per\nFerire, il fedele ottiene tuttavia un punto fede supplementare. Uno stesso fedele può designare un solo\ncombattente dotato di Martire per turno. Uno stesso combattente può essere designato una sola volta per\nturno.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 67, name: "Meccanico", description: "Un combattente con questa abilità può, durante la fase di mantenimento, provare a\nriparare le macchine da guerra o gli equipaggiamenti a Nafta o a Vapore in blocco dei suoi alleati (non quelli\ndistrutti da incidenti). Per poter provare ad effettuare la riparazione il meccanico deve essere libero da\navversari ed in contatto di base con la macchina o con l’alleato il cui equipaggiamento è in blocco. Se il\nbersaglio è una macchina da guerra che ha perso P.S. e che ha un equipaggiamento a vapore/nafta in\nblocco, il meccanico deve decidere quale dei due provare a riparare. Per effettuare la riparazione si lanci\n1D6: se il risultato è pari o superiore ad X la macchina recupera 1 P.S. o l’equipaggiamento a Vapore/Nafta\ntorna a funzionare. Con un 1 il meccanico non fa che aggravare le cose e la macchina perde 1 P.S. ulteriore\n(questo può distruggerla) o si deve effettuare un tiro di incidente per l’equipaggiamento a Nafta/Vapore.\nQualunque sia il numero di meccanici in contatto con la sua base, una stessa macchina da guerra può\nessere bersaglio di un solo tentativo di riparazione a turno, che esso sia un successo o meno.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 68, name: "Mercenario", description: "Un Mercenario può combattere nelle fila di qualsiasi esercito. È allora considerato\nun Alleato, a meno che non si batta per il proprio popolo di origine.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 69, name: "Mira", description: "Un qualsiasi tiratore dotato di armi da tiro, se non effettua nessun spostamento, può, una\nvolta per turno, dichiarare di ricorrere a questa abilità prima di procedere ad un test di tiro. Per questo tiro\negli aggiungerà alla forza della propria arma da tiro la rispettiva caratteristica di tiro, così come è stampata\nsulla carta di riferimento, però, per ogni incremento di gittata oltre la corta, la forza del tiro subirà un malus di\nun punto (-1 a media; - 2 a lunga). Inoltre valgono queste specifiche:\nI profili già in possesso dell’abilità Mira sulla carta possono usufruire dell’abilità anche se effettuano uno\nspostamento, ma il tal caso la difficoltà del tiro aumenterà di 1 punto.\nI Personaggi già in possesso dell’Abilità Mira sulla carta non risentono dei malus in FOR per l’incremento di\ngittata.\nMira non può essere utilizzata durante un Tiro in Assalto o un Tiro di Reazione.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 70, name: "Monaco-Guerriero", description: "Un Monaco-Guerriero beneficia dell’abilità Contrattacco e può cumulare\nazioni esclusive e Corsa col lancio di Incantesimi.\nEsempio\nSaphon può lanciare uno o più miracoli (azione cumulativa) e poi dichiarare una carica (azione esclusiva), un\ningaggio, un movimento in copertura o una corsa.\nMutageno/X (Attiva) : L’abilità Mutageno/X permette ai combattenti che ne sono dotati di beneficiare di\nbonus in determinate caratteristiche. Il suo utilizzo è subordinato alle regole seguenti.\n●​ Calcolo del numero di dadi di Mutageno/X: All’inizio di ogni turno, prima del Tiro di Tattica, si ottiene\nun dado di Mutageno per ogni frazione (anche incompleta) di 100 p.a. di combattenti alleati ancora\nin gioco e dotati di questa abilità (nel conteggio dei p.a. si tiene conto del costo del combattente e\ndei suoi costi addizionali).\n●​ Attribuzione dei dadi Mutageno/X: Una volta effettuato il calcolo del numero di dadi, ognuno di essi\ndeve essere immediatamente attribuito dal giocatore ad uno dei suoi combattenti dotati di\nMutageno/X. Uno stesso combattente può avere un solo dado di Mutageno/X per turno (salvo\neccezioni legate ad effetti particolari).\n●​ Determinazione del bonus di Mutageno/X: I dadi così attribuiti rappresentano un bonus potenziale\nche può essere aggiunto a determinate caratteristiche dei combattenti che ne beneficiano. A partire\ndal momento in cui un dado di Mutageno/X è stato attribuito ad un combattente, il giocatore può\nlanciarlo in qualsiasi momento durante il turno in corso per determinare il bonus. Per calcolare\nquest’ultimo, il risultato naturale del dado è modificato dal valore X associato all’abilità Mutageno/X\ndel combattente. Quando un dado di Mutageno viene lanciato per determinare un bonus, un 1 è\nconsiderato un fallimento automatico ed un non può essere aperto. Il risultato finale indica il numero\ndi punti che possono essere utilizzati per aumentare alcune caratteristiche del combattente.\nEsempio\nAl momento dell’attivazione del suo Guerriero Keratis, il giocatore Scorpione decide di lanciare il suo dado di\nMutageno/X. Ottiene un 3. Il Keratis dispone di Mutageno/1 quindi il risultato finale determina un bonus di\nquattro punti (3 +1 = 4).\nCaratteristiche che possono essere aumentate e bonus massimo: I punti di bonus così ottenuti possono\nessere utilizzati per aumentare MOV, INI, ATT, FOR, DIF e RES. Il numero massimo di punti di Mutageno/X\nche possono essere sommati ad una stessa caratteristica è uguale a 2 più il valore X dell’abilità del\ncombattente, se questo è positivo.\nEsempio\nDisponendo di Mutageno/-1, il clone di Dirz può assegnare un massimo di due punti bonus ad una stessa\ncaratteristica. Un guerriero Kératis dotato di Mutageno/1 può aggiungere fino a 3 punti bonus ad una stessa\ncaratteristica.\nRipartizione dei punti bonus: Una volta stabilito il bonus globale per un combattente, i punti possono essere\nutilizzati dal giocatore in qualsiasi momento, tenendo conto delle seguenti restrizioni:\n●​ L’aumento di una caratteristica non modifica in nessun caso un test già effettuato.\n●​ DIF e ATT d’un combattente possono essere aumentati solo all’inizio di un passo d’arme ma non\ndurante.\n●​ Gli incrementi delle statistiche così ottenuti non contano come scritti sulla carta del combattente.\nDurata delle modifiche Le modifiche di caratteristica dovute a Mutageno/X durano fino alla fine del turno in\ncorso. A fine turno i dadi ed i punti di Mutageno inutilizzati sono perduti.\nUn combattente che dispone sia di Mutageno/X che di Concentrazione non può utilizzare queste abilità\nassieme, ma deve scegliere quale delle due abilità utilizza (nel momento in cui ne avrà necessità sceglierà\nquale usare).", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 71, name: "Negazione", description: "Un combattente dotato di questa abilità non ha bisogno di vedere il suo bersaglio\nquando esercita la censura o la contromagia.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 72, name: "Nemico personale", description: "X rappresenta il nome di un Personaggio. Se il combattente uccide X,\negli recupera una Ferita. Il combattente guadagna inoltre un abilità a scelta tra Accanito; Autorità; Grido di\nraduno; Implacabile/1; Istinto di Sopravvivenza. Non è possibile scegliere un'abilità già posseduta. Una volta\nche una di queste abilità è stata acquisita, ne beneficia fino al termine della partita. I bonus legati a questa\nabilità non vengono acquisiti finché il nemico è ancora sul campo di battaglia (grazie all’abilità Accanito ad\nesempio.)", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 73, name: "Non-morto", description: "I Non-morti beneficiano delle abilità Immunità/Tossico ed Immunità/Paura, ma sono\nsensibili alla PAU causata di un Iperione. Inoltre, tutti i combattenti considerano i Non-morti avversari\nspaventosi, anche se sono dotati di una PAU superiore. Le regole relative alla paura si applicano quindi\nnormalmente. Quando è necessario effettuare un test utilizzando la DIS di un Non-morto, questo valore si\nconsidera nullo (DIS 0). Salvo eccezioni, un Non-morto può beneficiare dei vantaggi di Comando solo se\nquesti provengono da altri Non-morti.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 74, name: "Ossoduro", description: "Quando un combattente Ossoduro subisce un tiro per Ferire, il risultato deve essere\nletto una linea più in alto sulla tabella. Non è possibile risalire in questa maniera più in alto della prima linea\ndella tabella. Inoltre, quando un combattente Ossoduro viene caricato, la sua possanza è aumentata di 1\npunto per calcolare se subisce le penalità di Carica.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 75, name: "Parata", description: "Per questo combattente un 1 ottenuto in un test di DIF non è un fallimento, nemmeno se\nquesto risultato è stato ottenuto dopo aver aperto il dado.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 76, name: "Paria", description: "Se il combattente con cui si effettua il tiro di tattica è un Paria ma non tutti i combattenti\ndell’armata lo sono (evocati esclusi), i test di tattica sono effettuati con due dadi tenendo quello che mostra il\nrisultato peggiore.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 77, name: "Pietà", description: "I fedeli dotati di questa abilità possono conservare fino a X punti di F.T. da un turno\nall’altro, se ne possiedono in riserva al momento di calcolare la loro nuova F.T. I punti in riserva non si\ncumulano di turno in turno!", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 78, name: "Posseduto", description: "Un posseduto considera le penalità legate alle ferite inferiori di un livello. Così una\nferita non gli infligge nessuna penalità, due ferite gli infliggono le stesse penalità di una ferita e tre o più ferite\ngli infliggono le penalità di due ferite. Questa abilità non influisce sugli effetti degli stati Stordito e Ucciso. Un\nposseduto che è allo stesso tempo stordito e a una ferita subisce dunque le penalità legate allo stato di\nStordito.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 79, name: "Precisione", description: "I 5 ottenuti sui Test di Tiro del combattente possono essere aperti come se fossero 6.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 80, name: "Prevedibile", description: "La carta di riferimento di un combattente dotato di questa abilità è sempre\ndisposta in modo da essere scoperta nel mazzo del giocatore che lo controlla, e non coperta. Se questa\ncarta è posta in riserva, esse deve essere comunque visibile.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 81, name: "Rapidità", description: "Un combattente dotato di questa abilità può triplicare il suo MOV anziché raddoppiarlo\nquando carica, corre o fugge. Anche se si tratta di un’abilità attiva, rapidità può essere utilizzata da un\ncombattente in rotta. L’utilizzo di questa abilità è soggetta alla scelta del giocatore che controlla la miniatura,\nanche in caso di fuga.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 82, name: "Recupero", description: "Durante ogni fase mistica, dopo il suo tiro di recupero di mana e qualunque sia il\nrisultato di quest’ultimo il mago recupera X gemma addizionali, le gemme devono appartenere ad un\nElemento che egli domina. Questa abilità non permette al mago di possedere un numero di gemme\nsuperiore al massimo autorizzato dalla sua riserva di mana.\nRicarica rapida (Attiva) : Il combattente con questa abilità può effettuare anche la seguente azione\nesclusiva: il tiratore subisce un malus di -2 in tutte le sue prove di tiro fino al termine del turno, ma può\neffettuare un tiro addizionale. I tiri sono risolti separatamente (scelta del bersaglio, test di Tiro, Tiro per\nFerire), l’uno dopo l’altro, e possono essere diretti su bersagli differenti. Questa capacità può essere\ncumulata con qualsiasi altro effetto (equipaggiamento, incantesimo, miracolo, abilità, ecc.) che permetta al\nPersonaggio di effettuare tiri supplementari. Questa abilità non funziona quando il combattente che ne è\ndotato agisce in qualità di servente o sostituto di una macchina da guerra utilizzando il suo TIR per un tiro\ndel congegno.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 83, name: "Riflessi", description: "I 5 ottenuti sui Test di Iniziativa del combattente possono essere aperti come se fossero\n6.\nRigenerazione/X (Passiva) : Durante ogni fase di mantenimento, viene lanciato 1d6 per ogni combattente\nferito dotato di Rigenerazione/X. Qualora il risultato sia superiore o uguale a X, il livello di Ferite del\ncombattente è ridotto di uno. Se il test ha successo, il combattente effettua immediatamente un nuovo test\nalle stesse condizioni. Tuttavia, qualunque sia il risultato di questo secondo test, esso non può determinarne\nun terzo. Un combattente che sia stato ”Ucciso” non può in nessun caso beneficiare di Rigenerazione/X,\nanche se si trova ancora sul campo di battaglia grazie a qualche effetto di gioco (come l’abilità Accanito, ad\nesempio). Se un combattente con Rigenerazione/X acquisisce Effimero/X effettua solamente i tiri per\nquest’ultima abilità.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 84, name: "Rigore", description: "Un combattente dotato di questa abilità non considera gli 1 come un fallimento nelle sue\nprove di DIS (anche dopo aver aperto un 6).\nRinforzi (Passiva) : Quando un combattente dotato di questa abilità viene eliminato, la sua miniatura deve\nessere piazzata sul bordo del terreno (a meno che l’effetto che lo ha eliminato precisi che è “rimosso dalla\npartita”). Il gruppo così costituito viene chiamato Rinforzi. Se più eserciti hanno combattenti dotati di questa\nabilità, ognuno dispone dei propri Rinforzi. Durante ogni fase di mantenimento, ogni giocatore che dispone di\nrinforzi lanci 1d6. Il risultato ottenuto influenza il combattente dei Rinforzi che dispone del più basso valore\nstrategico (in PA):\nCon 1 o 2 il combattente è rimosso dai rinforzi. Egli non è rimosso dalla partita, ma non può essere oggetto\ndi un test di rinforzi;\nCon 3 o 4 nessun effetto;\nCon 5 o 6 il combattente torna sul campo di battaglia. Egli deve essere immediatamente piazzato ad una\ndistanza massima di 10 cm da un altro combattente del suo esercito e non può essere posto in contatto con\nun avversario. Allo stesso tempo, tutti gli effetti cui era soggetto al momento della morte sono dissipati\n(magie, miracoli, etc...) e le sue eventuali riserve di Gemme o Punti Fede sono vuote.\nI combattenti che rientrano in gioco grazie a Rinforzi, mantengono le capacità Solo e, se sono mistici,\nmantengono anche gli incantesimi ed i miracoli di cui erano eventualmente dotati in fase di costituzione delle\narmate.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 85, name: "Riorientamento", description: "Un combattente dotato di questa abilità e libero da ingaggio può variare\nliberamente il suo orientamento all’inizio di ogni fase di gioco. Questo riorientamento non è considerato uno\nspostamento.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 86, name: "Riparo", description: "Nessun combattente può atterrare a livello 0 in un raggio di X cm attorno ad una\nmacchina da guerra dotata di questa abilità.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 87, name: "Risolutezza", description: "L’utilizzo di questa abilità può essere utilizzato una volta per turno, subito prima di\nun test d’INI, ATT, DIF o COR del combattente che ne è dotato. Il risultato finale del test è aumentato di X.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 88, name: "Robustezza", description: "I combattenti dotati di questa abilità ignorano le Penalità legate a uno status di una\nsola Ferita subita e dello status di Stordito.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 89, name: "Rozzo", description: "Questo combattente può aprire i 5 che ottiene nelle sue prove di ATT come se fossero 6.\nQuando un combattente dotato di Rozzo effettua una Carica, la sua Possanza aumenta di 1 punto fino al\ntermine della sua attivazione.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 90, name: "Schivata", description: "I 5 ottenuti sui Test di Difesa del combattente possono essere aperti come se fossero 6.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 91, name: "Selenita", description: "I Seleniti dominano l’Acqua oltre agli elementi ai quali possono fare appello e\ndispongono della via Selenismo e di Alleanza/Wolfen d’Yllia. Inoltre, beneficiano di doni misteriosi la cui\nnatura dipende dalle fasi d’Yllia, la luna di Aarklash. All’inizio della partita, il giocatore che controlla il Selenita\ndeve lanciare 1d6. Se entrambe le armate dispongono di un combattente selenita, i giocatori possono\ndecidere di lanciare un singolo d6 o di lanciarne uno a testa; nel secondo caso verranno applicati gli effetti\ndel dado che mostra il risultato minore. In funzione del risultato ottenuto, il combattente beneficia di\ndeterminati bonus fino al termine della partita:\n●​ 1-2: Notte senza luna: nessun modificatore;\n●​ 3: Quarto di luna: +1 INI;\n●​ 4: Mezzaluna: +INI e DIF;\n●​ 5: Luna crescente: +1 in COR/PAU e DIS;\n●​ 6: Plenilunio: abilità Posseduto o Uccisore Nato o uno dei bonus legati alle fasi lunari precedenti;\ninoltre + 1 in POT o +1 in DIS.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 92, name: "Selvaggio", description: "Un combattente dotato di questa abilità beneficia di un +1 al risultato finale dei\nsuoi test di INI, ATT e DIF finché si trova ad una distanza superiore o uguale a X cm da ogni combattente\namico.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 93, name: "Senza Patria", description: "Un senza patria può essere inserito in qualsiasi esercito. Egli è allora considerato\nun Alleato. Il senza patria si integra così bene da guadagnare l’abilità più diffusa tra i suoi compagni d’armi.\nÈ il numero dei combattenti che possiedono l’abilità a determinarla e non il loro costo in p.a.. Se più abilità\nsono presenti nella stessa quantità, il giocatore che controlla il senza patria sceglie una di esse. Se si tratta\ndi un'abilità legata ad un valore, il senza patria acquista il valore più diffuso. ​\nAttenzione! le abilità con (*) NON possono essere acquisite dai Senza patria.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 94, name: "Sequenza di Colpi", description: "Un combattente dotato di Sequenza di colpi/X può acquisire fino a X dadi di\ncombattimento supplementari. Questa abilità può essere attivata nel momento in cui il giocatore che\ncontrolla il combattente suddivide i suoi dadi di combattimento. Ogni dado supplementare acquisito in questo\nmodo riduce l’ATT e la DIF del combattente di un punto. Le modifiche dovute a questa abilità durano solo per\nil combattimento in corso. Se partecipa a un nuovo combattimento nel corso dello stesso turno, il\ncombattente può nuovamente beneficiare di Sequenza di colpi/X. Se beneficia di altri effetti che donano\nSequenza di Colpi, il valore viene incrementato di altrettanti punti.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: "X" },
  { id: 95, name: "Spadaccino", description: "Quando i dadi di combattimento di uno Spadaccino sono ripartiti prima di un\ncombattimento, uno di essi è tenuto in riserva dal giocatore che lo controlla. Questo dado può essere\nutilizzato per risolvere qualsiasi azione (attacco, difesa, contrattacco, colpo da maestro, ecc.) durante un\nqualsiasi passo d’arme del combattimento e:\n●​ se è utilizzato come dado in attacco, questo attacco non può essere oggetto di Contrattacco,\nneppure grazie ad Ambidestro;\n●​ se è utilizzato come dado in difesa per effettuare una difesa sostenuta, non si subiscono i normali\nmalus per la difesa sostenuta.\nUn combattente dotato di questa abilità che ricorre alla Furia Guerriera beneficia del primo dei bonus in\nelenco per tutti i suoi attacchi.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 96, name: "Spirito di X", description: "X rappresenta uno dei sei elementi che governano l’uso della magia. Il Mago può\nuna volta per turno decidere che un suo 1 ottenuto in un test di potere non sia un fallimento automatico, ma\nsolo per un sortilegio che necessita esclusivamente di gemme di X per essere lanciato. Questa abilità non si\napplica se il sortilegio necessita di gemme di un altro Elemento. In ogni caso, le gemme utilizzate per\nmigliorare la maestria possono appartenere ad Elementi differenti.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 97, name: "Stratega", description: "I 5 ottenuti nei Test di Disciplina del combattente possono essere aperti come se\nfossero 6.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 98, name: "Taumaturgo", description: "L’aura di fede di un Fedele Taumaturgo è aumentata di 5 cm per ogni ferita\nsubita. Se il fedele viene guarito, la sua aura di fede deve essere modificata di conseguenza.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 99, name: "Tiratore d’élite", description: "Il combattente non considera un 1 come fallimento automatico nei suoi test di\nTiro. Questa abilità non è presa in considerazione se il combattente è Servente o Sostituto di una Macchina\nda Guerra.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 100, name: "Tiro in Assalto", description: "Un combattente dotato di questa abilità può tirare anche effettuando una carica o\nun impegno. Il tiratore deve disporre tuttavia di una linea di vista nei confronti del suo bersaglio all’inizio del\nsuo spostamento. Il tiro viene risolto prima che la miniatura sia spostata, rispettando le seguenti regole\nnell’ordine indicato:\n1.​ il tiro deve prendere di mira il bersaglio dell’assalto;\n2.​ la distanza tra il tiratore e il suo bersaglio deve essere misurata prima del tiro. Se il tiratore non è a\nportata di carica o d’ingaggio, il tiro non ha luogo e l’azione diventa una marcia con punto di arrivo\nil più vicino possibile al bersaglio originale;\n3.​ se il tiratore deve effettuare un test di Coraggio per poter caricare il suo bersaglio, il test deve essere\ntentato prima del tiro. In caso di fallimento, il combattente non tira;\n4.​ il tiro viene risolto con difficoltà 7, 4 se il combattente dispone dell’abilità Tiro in Assalto sulla carta o\nse la ottiene una seconda volta grazie a un effetto di gioco. Nessun altro modificatore (movimento,\nTaglia del bersaglio, Bersaglio/X, ecc.) può cambiare questa difficoltà;\n5.​ se il bersaglio deve effettuare un test di Coraggio nei confronti del tiratore, questo deve essere\neffettuato dopo la risoluzione del tiro.\nA meno che non sia indicato diversamente, un combattente può effettuare un solo tiro in assalto, qualunque\nsia il numero di tiri a cui abbia diritto in virtù delle sue abilità e del suo equipaggiamento. Se il bersaglio è\neliminato prima del tiro o dal tiro, il combattente può ridirezionare il suo assalto verso un altro bersaglio, ma\nnon può effettuare un secondo tiro in assalto. In questo caso, si utilizzano le regole usate nel caso del\nridirezionamento della carica dei combattenti spaventosi. Se più combattenti effettuano simultaneamente un\ntiro in assalto contro lo stesso bersaglio, tutti i loro tiri devono essere risolti prima dello spostamento delle\nminiature.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 101, name: "Tiro Istintivo", description: "La difficoltà dei tiri di questo combattente non tiene conto dei malus dovuti alla\ncopertura o all’utilizzo delle abilità Assillo o Mira. Inoltre, quando questo combattente effettua un test di\nripartizione in seguito a un tiro in mischia, egli colpisce un combattente del suo esercito solo con un risultato\ndi 1. Con un 2 egli non colpisce nessuno e con 3 o più colpisce un avversario. Questa abilità non funziona\nquando il combattente funge da sostituto di una macchina da guerra e il suo TIR è utilizzato per un tiro del\ncongegno.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 102, name: "Tiro di Reazione", description: "Un tiratore con questa abilità può, nel momento in cui viene effettuato un assalto\ncontro di lui (e quindi dopo eventuali test di Coraggio), effettuare un tiro contro uno degli assaltatori. Affinché\negli possa effettuare questo tiro devono verificarsi le seguenti condizioni:\nla carta del tiratore non deve essere ancora stata attivata;\n1.​ il tiratore deve vedere il suo assaltatore nel momento in cui questi dichiara il suo assalto;\n2.​ il tiratore deve essere libero da altri ingaggi.\nIl tiro viene risolto con difficoltà 7, 4 se il combattente dispone dell’abilità Tiro di Reazione sulla carta o se\nottiene nuovamente questa abilità grazie ad un effetto di gioco. Nessun altro modificatore (movimento, Taglia\ndel bersaglio, Bersaglio/X, ecc.) può cambiare questa difficoltà;\nAll’attivazione del tiratore, se ha già fatto uso di Tiro di reazione, in caso fosse libero da ingaggi non potrà\nprocedere ad alcun tiro né potrà effettuare un’azione esclusiva o una corsa. Se alla carta del tiratore sono\nassociati altri tiratori, questi potranno essere attivati normalmente durante la loro attivazione o, se ne\navranno l’occasione, effettuare i loro tiri di reazione secondo le condizioni prima enunciate.\nInoltre valgono le seguenti regole:\n1.​ ogni combattente ha diritto ad un solo tiro di reazione per turno; la difficoltà di un tiro di reazione\ncontro un nemico in picchiata è 7;\n2.​ non si possono combinare le abilità Mira e Tiro di Reazione;\n3.​ se l’assaltatore effettua un tiro in assalto e il difensore vuole procedere a un tiro di reazione, si\nrisolve prima il tiro in assalto;\n4.​ i serventi di una macchina da guerra non possono effettuare un Tiro in Reazione usando la\nmacchina, a meno che la macchina stessa abbia l’abilità Tiro di Reazione.\nPer i combattenti di artiglieria con questa abilità vale inoltre la seguente limitazione:\n1.​ il tiro viene risolto come un tiro normale, e non secondo le regole dell’artiglieria perforante o a zona,\ne non beneficia dei bonus da esse garantite.\nTossico (Passiva):\n●​ Calcolo del numero di dadi Tossico/X - Prima di ogni tiro di tattica ogni giocatore ottiene un dado di\nTossico per ogni 100 pa, anche incompleti, di suoi combattenti con questa abilità ancora vivi sul\ncampo.\n●​ Attribuzione dei dadi di Tossico/X Una volta effettuato il calcolo del numero di dadi, ognuno di essi\ndeve essere immediatamente attribuito dal giocatore ad uno dei suoi combattenti dotati di Tossico/X.\nUno stesso combattente può beneficiare di un solo dado di Tossico per turno, salvo eccezioni legate\nad effetti particolari, e non può avere più di un dado di tossico alla volta.\n●​ Effetti dei dadi di Tossico/X. Quando un combattente beneficia di un dado Tossico, il giocatore che lo\ncontrolla può scegliere uno dei suoi Tiri o uno dei suoi Attacchi, rendendolo tossico. Questa scelta va\nannunciata PRIMA del test di caratteristica corrispondente (nel caso dell’attacco prima, che\nl’avversario abbia dichiarato se difendere o no). Se il test è fallito o se non viene inflitta nessuna\nferita, il dado Tossico è perso. Se questo tiro o questo attacco infligge almeno una ferita (Stordito\nnon è una ferita), il giocatore effettua immediatamente un secondo tiro per ferire contro lo stesso\nbersaglio. Per questo nuovo Test, la FOR dell’attacco è uguale a X (Tossico/3 quindi FOR 3), e la\nRES del bersaglio è considerata uguale a 0, quali che siano gli effetti di cui egli beneficia. Tuttavia,\ngli effetti che influiscono sui risultati dei tiri per ferire si applicano normalmente.\n●​ Limitazioni degli effetti di Tossico/X. Un Test per ferire inflitto da Tossico/X non beneficia mai degli\neffetti che si applicano ai normali attacchi del combattente. Esso non beneficia di bonus in FOR, di\nFlagello/X, di Assassino e di ogni altro effetto che si applica ai tiri per ferire (a meno che non sia\nespressamente specificato altrimenti). I non-morti ed i costrutti sono immuni agli effetti di Tossico/X,\nmentre gli Immortali leggono le ferite dovute al tossico una riga più in alto nella tabella delle ferite.\n●​ Durata degli effetti di Tossico/X. Gli effetti di un dado Tossico si applicano solo al primo tiro per ferire\ncausato dall’attacco o dal tiro designato. Alla fine del turno, durante i tempi morti, tutti i dadi di\nTossico/x inutilizzati sono perduti.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 103, name: "Uccisore Nato", description: "In corpo a corpo i combattenti dotati di questa abilità beneficiano di un dado di\ncombattimento supplementare rispetto a quelli ai quali hanno normalmente diritto. Inoltre, un combattente\ndotato di questa abilità supera automaticamente i test di Coraggio la cui difficoltà sia inferiore o uguale al\nCOR che utilizza, anche se quest’ultimo gli è stato trasmesso da un comandante.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 104, name: "Vivacità", description: "Gli 1 non sono fallimenti nei test di INI di un combattente dotato di questa abilità, anche\nse ottenuti dopo aver aperto un 6.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 105, name: "Volo", description: "Le miniature che dispongono di volo devono essere schierate a contatto col suolo (livello\n0), a meno che lo scenario non indichi diversamente, e possono utilizzare le regole relative al combattimento\naereo descritte a pag XX.​\nIl massimo di combattenti con Volo che possono essere presenti in un’armata è pari al 65% dell’armata in\np.a..", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
  { id: 106, name: "Vulnerabile", description: "La gravità delle ferite subite (dopo l’applicazione degli eventuali modificatori) da un\ncombattente dotato di questa abilità è peggiorata di un livello. Una ferita diventano due. Due diventano tre, e\ncosì via. I risultati di Stordito non sono modificati.", created_at: "2025-12-28T14:40:47Z", updated_at: "2025-12-28T14:40:47Z", value: nil },
])
